-- Function: set-returning, with a loop and an exception handler
CREATE OR REPLACE FUNCTION claim_next_job(p_queue text)
RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
    v_id bigint;
BEGIN
    SELECT id INTO v_id
    FROM jobs
    WHERE queue = p_queue AND status = 'pending'
    ORDER BY id
    FOR UPDATE SKIP LOCKED
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    UPDATE jobs SET status = 'running', started_at = now() WHERE id = v_id;
    RETURN v_id;
END;
$$;
```
