-- Procedure with intermediate commits (batch purge)
CREATE PROCEDURE purge_old_events(p_days int) LANGUAGE plpgsql AS $$
DECLARE n int;
BEGIN
    LOOP
        DELETE FROM events WHERE id IN (
            SELECT id FROM events WHERE created_at < now() - make_interval(days => p_days) LIMIT 10000);
        GET DIAGNOSTICS n = ROW_COUNT;
        COMMIT;
        EXIT WHEN n = 0;
    END LOOP;
END;
$$;
CALL purge_old_events(90);
